Lemma bootl_0RB1LA_1LC1RD_1RB0LA_1LC1RC :
  stepn tm 20 InitES = Some (lift (fam_cfg FAM ([0], 0, 2))).
Proof.
  assert (H : match csteps tm 20 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 2))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 20 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestPvTr.boardPv_neverqhtr]. *)
Theorem nqhtr_0RB1LA_1LC1RD_1RB0LA_1LC1RC : NeverQuasiHaltsTr tm_0RB1LA_1LC1RD_1RB0LA_1LC1RC.
Proof.
  eapply (boardPv_neverqhtr tm_0RB1LA_1LC1RD_1RB0LA_1LC1RC pins_0RB1LA_1LC1RD_1RB0LA_1LC1RC FAM 3
