  mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]))
          (mkC StB (mkS [] [] 0 0 []) S1 (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0])) 0 1.
