  match r, ph with
  | 1, 0 => farm1_0_0RB1RB_1RC0LD_1LB1RA_0RC1LD
  | 1, 1 => farm1_1_0RB1RB_1RC0LD_1LB1RA_0RC1LD
  | 1, 2 => farm1_2_0RB1RB_1RC0LD_1LB1RA_0RC1LD
  | 1, 3 => farm1_3_0RB1RB_1RC0LD_1LB1RA_0RC1LD
