  | 1, (StB, S0) => [SWinL 5;SCycR 3;SWinR 5]
  | 1, (StB, S1) => [SWinL 3]
  | 1, (StC, S0) => [SWinL 1]
  | 1, (StC, S1) => [SWinL 5;SCycR 3;SWinR 7]
  | 1, (StD, S0) => [SWinL 5;SCycR 3;SWin 2]
  | 1, (StD, S1) => [SWinL 4]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_1RB0LC_1LA1RD_0RA1LC_1RB1RA (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
