  d < fm_b FAM - 1 -> r < 0 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB0LC_1LA1RD_0RB1LC_0LD1RA d r).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LC_1LA1RD_0RB1LC_0LD1RA | exact ok_iarm0_0_1RB0LC_1LA1RD_0RB1LC_0LD1RA]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

