Local Notation FAM := fam_1RB0LD_0RC1RA_1LC1LA_0RA1LD.

(** ** The ladder, as DATA

    5 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LD_0RC1RA_1LC1LA_0RA1LD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StB (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StB (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StB (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StB (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB0LD_0RC1RA_1LC1LA_0RA1LD.

Definition rules_1RB0LD_0RC1RA_1LC1LA_0RA1LD : list LRule := map fst lad.
Local Notation rules := rules_1RB0LD_0RC1RA_1LC1LA_0RA1LD.

Lemma ladder_ok_1RB0LD_0RC1RA_1LC1LA_0RA1LD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LD_0RC1RA_1LC1LA_0RA1LD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LD_0RC1RA_1LC1LA_0RA1LD. Qed.

(** ** The arms, as DATA

