  match r, t with
  | 1, (StA, S0) => [SWin 2]
  | 1, (StA, S1) => [SWin 2;SCycR 2;SWinR 7]
  | 1, (StB, S0) => [SWin 2;SCycR 2;SWinR 3]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWin 2;SCycR 2;SWinR 4]
  | 1, (StC, S1) => [SWin 2;SCycR 2;SWinR 6]
  | 1, (StD, S0) => []
