Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LB_1LC0RD_1RB1LA_0LC1RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LB_1LC0RD_1RB1LA_0LC1RD
  | _, _ => iarm0_0_1RB1LB_1LC0RD_1RB1LA_0LC1RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB1LB_1LC0RD_1RB1LA_0LC1RD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB1LB_1LC0RD_1RB1LA_0LC1RD
  | 1, 1 => farm1_1_1RB1LB_1LC0RD_1RB1LA_0LC1RD
  | 1, 2 => farm1_2_1RB1LB_1LC0RD_1RB1LA_0LC1RD
  | _, _ => farm1_0_1RB1LB_1LC0RD_1RB1LA_0LC1RD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1LB_1LC0RD_1RB1LA_0LC1RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 1 | 1, 2 => 0 | _, _ => 0 end.
Definition fm2_1RB1LB_1LC0RD_1RB1LA_0LC1RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 0 | 1, 2 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    1.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB1LB_1LC0RD_1RB1LA_0LC1RD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 3;SCycL 3 0;SWinL 2]
  | 1, (StA, S1) => [SWin 2]
  | 1, (StB, S0) => [SWin 3]
  | 1, (StB, S1) => [SWin 3;SCycL 3 0;SWin 2]
  | 1, (StC, S0) => [SWin 3;SCycL 3 0;SWin 1]
  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => []
  | 1, (StD, S1) => [SWin 3;SCycL 3 0;SWin 2;SRotR 1;SWin 1]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_1RB1LB_1LC0RD_1RB1LA_0LC1RD (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | _, _ => []
  end.

(** The visit phase of each instruction ([LadderCheckNestPvTr]), and the
    fills it takes the phase cycle to reach it from each phase. *)
Definition pvf_1RB1LB_1LC0RD_1RB1LA_0LC1RD (t : Instr) : nat :=
  match t with
  | (StA, S0) => 1
  | (StA, S1) => 0
  | (StB, S0) => 0
  | (StB, S1) => 0
  | (StC, S0) => 0
  | (StC, S1) => 0
  | (StD, S0) => 0
  | (StD, S1) => 0
  end.

Definition kcyc_1RB1LB_1LC0RD_1RB1LA_0LC1RD (tg ph : nat) : nat :=
  match tg, ph with
  | 0, 0 => 0
  | 0, 1 => 1
  | 0, 2 => 2
  | 1, 0 => 2
  | 1, 1 => 0
  | 1, 2 => 1
  | _, _ => 0
  end.

Lemma pvlt_1RB1LB_1LC0RD_1RB1LA_0LC1RD : forall t, pvf_1RB1LB_1LC0RD_1RB1LA_0LC1RD t < 3.
Proof. intros [q s]; destruct q, s; vm_compute; lia. Qed.

Lemma cyc_1RB1LB_1LC0RD_1RB1LA_0LC1RD : forall t ph, ph < 3 ->
  exists k, phto FAM k ph = pvf_1RB1LB_1LC0RD_1RB1LA_0LC1RD t.
Proof.
  intros t ph Hph. exists (kcyc_1RB1LB_1LC0RD_1RB1LA_0LC1RD (pvf_1RB1LB_1LC0RD_1RB1LA_0LC1RD t) ph).
  destruct t as [q s]; destruct q, s;
    (do 3 (destruct ph as [|ph]; [vm_compute; reflexivity|])); lia.
Qed.

Lemma iarm_reach_1RB1LB_1LC0RD_1RB1LA_0LC1RD : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (iarm_1RB1LB_1LC0RD_1RB1LA_0LC1RD d r)) (lr_rhs (iarm_1RB1LB_1LC0RD_1RB1LA_0LC1RD d r)).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1LB_1LC0RD_1RB1LA_0LC1RD | exact ok_iarm0_0_1RB1LB_1LC0RD_1RB1LA_0LC1RD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma iarm_lhs_1RB1LB_1LC0RD_1RB1LA_0LC1RD : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  lr_lhs (iarm_1RB1LB_1LC0RD_1RB1LA_0LC1RD d r)
    = cls_conf FAM (cls_side FAM [] (fm_b FAM - 1) r
                      (astride 0 1 r) [d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { vm_compute; reflexivity. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma iarm_rhs_1RB1LB_1LC0RD_1RB1LA_0LC1RD : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  lr_rhs (iarm_1RB1LB_1LC0RD_1RB1LA_0LC1RD d r)
    = cls_conf FAM (cls_side FAM [] 0 r (astride 0 1 r) [S d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { vm_compute; reflexivity. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

