Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1LC_1LA0RD_0RC1LB_0LB1RD : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1LC_1LA0RD_0RC1LB_0LB1RD. Qed.

