Lemma bootl_1RB1LC_1LA0RD_0RC1LB_0LB1RD :
  stepn tm 31 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm 31 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 31 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB1LC_1LA0RD_0RC1LB_0LB1RD : NeverQuasiHaltsTr tm_1RB1LC_1LA0RD_0RC1LB_0LB1RD.
Proof.
