Lemma farm_sound_1RB1LC_1LA0RD_1LA1LB_0LA1RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 4 -> RuleSound tm true true (farm_1RB1LC_1LA0RD_1LA1LB_0LA1RD r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
