(** ** What this board establishes

    19 of 19 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 19 of them
    collapse to 5 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0])) 6 6.
Definition ch_iarm0_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD : list rstep := [RB (SRotR 1);RB (SWin 1);RB (SCycR 3);RB (SWin 4);RB (SCycL 3 0);RB (SWin 1);RB (SUnrotR 1)].
Lemma ok_iarm0_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD :
  check_arm tm true false rules iarm0_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD
            ch_iarm0_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1RC_1LC1RA_1RB0LD_0RB1LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD
  | _, _ => iarm0_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0] [S1;S1;S0] 1 0 [S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S0;S1])) 6 12.
Definition ch_farm1_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWin 1);RB (SWinR 5);RB (SCycL 3 0);RB (SWin 3)].
Lemma ok_farm1_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD :
  check_arm tm true true rules farm1_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD
            ch_farm1_0_1RB1RC_1LC1RA_1RB0LD_0RB1LD = true.
Proof. vm_compute. reflexivity. Qed.

