Lemma vis_ok_1RB1RC_1LC1RA_1RB0LD_0RC1LD : forall r t, ~ In t pins_1RB1RC_1LC1RA_1RB0LD_0RC1LD -> 0 < r ->
  r < 1 + 1 ->
  nfire tm true true nrules (vsegs_1RB1RC_1LC1RA_1RB0LD_0RC1LD r t) (vis_1RB1RC_1LC1RA_1RB0LD_0RC1LD r t)
    (lr_lhs (farm_1RB1RC_1LC1RA_1RB0LD_0RC1LD r 1)) = Some t.
Proof.
  intros r t Hnp H0 Hr.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  { destruct t as [q s]; destruct q, s; try (exfalso; apply Hnp; simpl; tauto); vm_compute; reflexivity. }
  exfalso; lia.
Qed.

Lemma bootl_1RB1RC_1LC1RA_1RB0LD_0RC1LD :
  stepn tm 26 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm 26 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 26 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB1RC_1LC1RA_1RB0LD_0RC1LD : NeverQuasiHaltsTr tm_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
Proof.
  eapply (boardN_neverqhtr tm_1RB1RC_1LC1RA_1RB0LD_0RC1LD pins_1RB1RC_1LC1RA_1RB0LD_0RC1LD FAM 4
                           iarm_1RB1RC_1LC1RA_1RB0LD_0RC1LD 0 1
                           farm_1RB1RC_1LC1RA_1RB0LD_0RC1LD 1 1
                           fm1_1RB1RC_1LC1RA_1RB0LD_0RC1LD fm2_1RB1RC_1LC1RA_1RB0LD_0RC1LD 1
                           nrules vsegs_1RB1RC_1LC1RA_1RB0LD_0RC1LD vis_1RB1RC_1LC1RA_1RB0LD_0RC1LD
                           [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 3; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 2; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_reach_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
  - exact iarm_lhs_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
  - exact iarm_rhs_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
  - lia.
  - lia.
  - exact farm_reach_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
  - exact farm_lhs_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
  - exact farm_rhs_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
  - exact nrules_sound_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
  - exact vis_ok_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
  - exact bootl_1RB1RC_1LC1RA_1RB0LD_0RC1LD.
Qed.

